INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','clefts-emphasis','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"clefts-emphasis","title":"Cleft sentences and emphatic do","level":"C1","order":63,"summary":"Focus the reader’s attention on a participant, an action or a correction.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["It-clefts","What-clefts","Emphatic do","Choose emphasis for a reason"],"rules":[{"title":"It-clefts","explanation":"An it-cleft divides a message into a focused part and a following clause: **It was X who/that ...**. The focus can be a person, thing, time or place. Use a form that makes the intended contrast clear.","pattern":"**It was the guide who** called.","commonMistakes":["It in an it-cleft is a grammatical device; it does not refer back to a thing."],"examples":["Correct the claim that she never does the task: “She does **prepare** the visitor guide!”","Correct the claim that she never does the task: “She does **restore** the old portrait!”"],"skill":"form"},{"title":"What-clefts","explanation":"A what-clause can introduce the part of the message already under discussion, followed by be and the focus. What I need is a break focuses on a break. After what + do, the focused action commonly uses a base infinitive, with to also possible in many contexts.","pattern":"**What I need is** more time. / **What she did was (to) call**.","commonMistakes":["Do not reject the to variant after what she did was merely because a bare infinitive is also possible."],"examples":["Correct a denial about yesterday: “We did **prepare** the visitor guide!”","Correct a denial about yesterday: “We did **restore** the old portrait!”"],"skill":"meaning"},{"title":"Emphatic do","explanation":"Use do, does or did in an affirmative clause to contradict a negative assumption or add emphasis. The auxiliary carries tense and agreement, so the main verb uses its base form. Spoken stress falls on the auxiliary.","pattern":"She **does know**. / We **did call**.","commonMistakes":["She does knows marks agreement twice; use does know."],"examples":["Focus on the person: “It was the assistant **who** prepared the visitor guide.”","Focus on the person: “It was the assistant **who** restored the old portrait.”"],"skill":"contrast"},{"title":"Choose emphasis for a reason","explanation":"Clefts and emphatic auxiliaries make information prominent. Too many in a paragraph can make prose heavy. Choose the structure according to what the listener already knows and which contrast matters. Written emphasis should still leave the underlying grammar clear.","pattern":"It was **yesterday** that we called.","commonMistakes":["Clefts are not needed simply to make every sentence sound more advanced."],"examples":["Complete the what-cleft: “What I need **is** time to prepare the visitor guide.”","Complete the what-cleft: “What I need **is** time to restore the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-emphasis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"9e8a00fa-9119-5dc5-a5da-b4ac12a079fb","topicSlug":"clefts-emphasis","level":"C1","prompt":"Correct the claim that she never does the task: “She does ____ the visitor guide!”","choices":[{"id":"A","text":"prepare"},{"id":"B","text":"prepares"},{"id":"C","text":"prepared"},{"id":"D","text":"to prepare"}],"answerId":"A","hint":"Emphasis adds **does**, which takes over the agreement marking.","explanation":"Emphatic **does** carries the agreement, so choose base **prepare**.","keywords":["emphatic-present"],"skill":"emphatic-present","contextKey":"clefts-emphasis-1","fingerprint":"afee3e45a66c58511712808781b547cfcbd6a2d02e110835e0c2f0b75c9414d6","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-emphasis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Emphasis adds **does**, which takes over the agreement marking.","Emphatic **does** carries the agreement, so choose base **prepare**.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Emphatic **does** carries the agreement, so choose base **prepare**.","B":"The -s agreement is already on does.","C":"Does is present; the following verb still needs base form.","D":"Emphatic do takes a bare infinitive."}}},{"id":"0456f81e-f36e-59e0-af19-12e8b7054ebc","topicSlug":"clefts-emphasis","level":"C1","prompt":"Correct a denial about yesterday: “We did ____ the visitor guide!”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepare"},{"id":"C","text":"prepared"},{"id":"D","text":"prepares"}],"answerId":"B","hint":"The auxiliary carries both **past tense and emphasis**.","explanation":"Emphatic **did** carries the past tense, so use **prepare**.","keywords":["emphatic-past"],"skill":"emphatic-past","contextKey":"clefts-emphasis-1","fingerprint":"558a56ea375a1af8e8aeb2e30d2441a6509b2282a30cc0a3284dc3c4e8f647b1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-emphasis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The auxiliary carries both **past tense and emphasis**.","Emphatic **did** carries the past tense, so use **prepare**.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did takes a bare infinitive.","B":"Emphatic **did** carries the past tense, so use **prepare**.","C":"The past marker is already on did.","D":"A third-person present form cannot follow did."}}},{"id":"c9ba163a-ddff-5816-a90b-643cf86c7b24","topicSlug":"clefts-emphasis","level":"C1","prompt":"Focus on the person: “It was the assistant ____ prepared the visitor guide.”","choices":[{"id":"A","text":"who"},{"id":"B","text":"whose"},{"id":"C","text":"where"},{"id":"D","text":"what"}],"answerId":"A","hint":"The focused element is a **person**, and the following clause needs its subject.","explanation":"**Who** links the focused person to the action in this it-cleft.","keywords":["person-cleft"],"skill":"person-cleft","contextKey":"clefts-emphasis-1","fingerprint":"4e441e75a8d7da0a1b59df864845c7440067d9032b2cbb8c9994bc6631bc9296","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-emphasis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The focused element is a **person**, and the following clause needs its subject.","**Who** links the focused person to the action in this it-cleft.","Choose **who**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Who** links the focused person to the action in this it-cleft.","B":"Whose would need a noun after it to mark possession.","C":"Where does not represent the person performing this action.","D":"What does not normally follow a named person as the cleft connector here."}}},{"id":"426291f0-e1f3-560d-aaea-321f14e4c572","topicSlug":"clefts-emphasis","level":"C1","prompt":"Complete the what-cleft: “What I need ____ time to prepare the visitor guide.”","choices":[{"id":"A","text":"is"},{"id":"B","text":"are"},{"id":"C","text":"be"},{"id":"D","text":"am"}],"answerId":"A","hint":"The subject is the whole **what I need** clause, not the I inside it.","explanation":"The what-clause presents a single need, so **is** links it to time.","keywords":["what-cleft-agreement"],"skill":"what-cleft-agreement","contextKey":"clefts-emphasis-1","fingerprint":"876bbae7ecc9485b5e5da276947bb3ff5528605472172fc8d5fc4bda56e8f136","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-emphasis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The subject is the whole **what I need** clause, not the I inside it.","The what-clause presents a single need, so **is** links it to time.","Choose **is**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The what-clause presents a single need, so **is** links it to time.","B":"The complement is uncountable time and the clause presents one need, so plural are does not fit this example.","C":"Be is not a finite present form.","D":"Am agrees with I as a main subject, not with the whole what-clause."}}},{"id":"c90ab48d-5ab3-5c1f-a42f-5b7cb6f8156b","topicSlug":"clefts-emphasis","level":"C1","prompt":"Correct the claim that she never does the task: “She does ____ the old portrait!”","choices":[{"id":"A","text":"restore"},{"id":"B","text":"restores"},{"id":"C","text":"restored"},{"id":"D","text":"to restore"}],"answerId":"A","hint":"Emphasis adds **does**, which takes over the agreement marking.","explanation":"Emphatic **does** carries the agreement, so choose base **restore**.","keywords":["emphatic-present"],"skill":"emphatic-present","contextKey":"clefts-emphasis-2","fingerprint":"66263a48512de8ce4602aec6f41d4887a2e1d9450718709af8b20767f1cb8406","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-emphasis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Emphasis adds **does**, which takes over the agreement marking.","Emphatic **does** carries the agreement, so choose base **restore**.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Emphatic **does** carries the agreement, so choose base **restore**.","B":"The -s agreement is already on does.","C":"Does is present; the following verb still needs base form.","D":"Emphatic do takes a bare infinitive."}}},{"id":"1c427dfb-c3a3-5c3d-a470-36cfe544b9cd","topicSlug":"clefts-emphasis","level":"C1","prompt":"Correct a denial about yesterday: “We did ____ the old portrait!”","choices":[{"id":"A","text":"restores"},{"id":"B","text":"to restore"},{"id":"C","text":"restore"},{"id":"D","text":"restored"}],"answerId":"C","hint":"The auxiliary carries both **past tense and emphasis**.","explanation":"Emphatic **did** carries the past tense, so use **restore**.","keywords":["emphatic-past"],"skill":"emphatic-past","contextKey":"clefts-emphasis-2","fingerprint":"c71b7891d4d2d2152ccfb8edb7e18dc5904ad919720a686642e5d397e5e3e34a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-emphasis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The auxiliary carries both **past tense and emphasis**.","Emphatic **did** carries the past tense, so use **restore**.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A third-person present form cannot follow did.","B":"Did takes a bare infinitive.","C":"Emphatic **did** carries the past tense, so use **restore**.","D":"The past marker is already on did."}}},{"id":"d4184a30-3915-58c7-ac19-54f60b72ca8a","topicSlug":"clefts-emphasis","level":"C1","prompt":"Focus on the person: “It was the assistant ____ restored the old portrait.”","choices":[{"id":"A","text":"where"},{"id":"B","text":"what"},{"id":"C","text":"who"},{"id":"D","text":"whose"}],"answerId":"C","hint":"The focused element is a **person**, and the following clause needs its subject.","explanation":"**Who** links the focused person to the action in this it-cleft.","keywords":["person-cleft"],"skill":"person-cleft","contextKey":"clefts-emphasis-2","fingerprint":"94a2481dce8dbee71094a2113cc6a3